# One jaw is outside the right bowl and the other is inside its front wall.
# Descend slightly, close on the rim, and make a small lift to test retention.
obs, used, outcome = move_ee('right', [0.20, -0.27, 0.945] + q_down, 0.7, 20)
print('contact', used, outcome)
if outcome == 'reached':
    obs, used, outcome = move_ee('right', list(obs['state']['right_ee_pose']), 0.0, 12)
    for i in range(6):
        if outcome == 'ended':
            break
        obs, reward, terminated, truncated, info = step({'right_ee_pose': obs['state']['right_ee_pose'], 'left_ee_pose': obs['state']['left_ee_pose'], 'right_ee_joint_state': [0.0], 'left_ee_joint_state': [1.0]})
        if terminated or truncated:
            outcome = 'ended'
    if outcome != 'ended':
        obs, used, outcome = servo_translate('right', [0.20, -0.27, 1.015], 0.0, 25)
        print('lift', used, outcome, obs['state']['right_ee_pose'])

