# The bowl is aligned above the middle bowl at low height.
# Lower a little farther, release gently, then clear the stack and return the right arm home.
obs, used, outcome = servo_translate('right', [-0.035, -0.29, 0.97], 0.0, 12)
print('seat', used, outcome)
if outcome == 'reached':
    pose = list(obs['state']['right_ee_pose'])
    left_pose = list(obs['state']['left_ee_pose'])
    for i in range(12):
        obs, reward, terminated, truncated, info = step({'right_ee_pose': pose, 'left_ee_pose': left_pose, 'right_ee_joint_state': [1.0], 'left_ee_joint_state': [1.0]})
        if terminated or truncated:
            outcome = 'ended'
            break
    if outcome != 'ended':
        obs, used, outcome = servo_translate('right', [-0.035, -0.29, 1.13], 1.0, 35)
        print('clear', used, outcome)
    if outcome == 'reached':
        for i in range(30):
            obs, reward, terminated, truncated, info = step(home)
            if terminated or truncated:
                break
        print('home', reward, info)

