# The third bowl is aligned at low height above the two-bowl stack.
# Release, withdraw vertically, and return home while checking the official completion signal.
obs = get_observation()
pose = list(obs['state']['left_ee_pose'])
other_pose = list(obs['state']['right_ee_pose'])
outcome = 'released'
for i in range(12):
    obs, reward, terminated, truncated, info = step({'left_ee_pose': pose, 'right_ee_pose': other_pose, 'left_ee_joint_state': [1.0], 'right_ee_joint_state': [1.0]})
    if terminated or truncated:
        outcome = 'ended'
        break
if outcome != 'ended':
    obs, used, outcome = servo_translate('left', [-0.035, -0.29, 1.13], 1.0, 32)
    print('clear', used, outcome)
if outcome == 'reached':
    for i in range(40):
        obs, reward, terminated, truncated, info = step(home)
        if terminated or truncated:
            break
    print('home', i + 1, reward, info, obs['state'])

